css:
.toggle {
  display: inline-block;
  cursor: pointer;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.toggle input {
  display: none;
}

.track {
  position: relative;
  display: block;
  width: 41px;
  height: 22px;
  background: #080808;
  border-radius: 15px;
  transition: background 0.25s;
}

.thumb {
  position: absolute;
  top: 2.5px;
  left: 2.3px;
  width: 27px;
  height: 17px;
  background: #fff;
  border-radius: 8px;
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow:
    0 1px 2px rgba(0, 0, 0, 0.35),
    0 6px 12px rgba(0, 0, 0, 0.18);
}

.toggle input:checked + .track .thumb {
  transform: translateX(9px);
}
